package com.coworkhub.entity;
import jakarta.persistence.*;import java.time.LocalDateTime;import java.math.BigDecimal;import java.util.*;
@Entity @Table(name="bookings") public class Booking { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; public LocalDateTime startTime,endTime; public int attendees; @Enumerated(EnumType.STRING) public Enums.BookingStatus status=Enums.BookingStatus.PENDING; @Column(precision=10,scale=2) public BigDecimal roomCost=BigDecimal.ZERO; @Column(precision=10,scale=2) public BigDecimal servicesCost=BigDecimal.ZERO; @Column(precision=10,scale=2) public BigDecimal totalCost=BigDecimal.ZERO; @Column(precision=10,scale=2) public BigDecimal cancellationFee=BigDecimal.ZERO; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(nullable=false) public Room room; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(nullable=false) public Member member; @com.fasterxml.jackson.annotation.JsonIgnore @OneToMany(mappedBy="booking",cascade=CascadeType.ALL,orphanRemoval=true) public List<BookingItem> items=new ArrayList<>(); public Booking(){} }
